// Checks the REAL code on GitHub and the REAL live site — nobody types
// "done" into anything. If a check can't run (site down, file missing), it
// just reports pending; it never guesses.
const owner = 'inder20216';
const repo = 'openmind360';

const fetchRaw = async (path) => {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://raw.githubusercontent.com/${owner}/${repo}/main/${path}`,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
    });
    return (res.statusCode >= 200 && res.statusCode < 300) ? String(res.body) : null;
  } catch (e) { return null; }
};

const [viteConfig, indexHtml, serviceDetailJsx, caseStudiesJsx, contactForm, trustStats, chatWidget] = await Promise.all([
  fetchRaw('vite.config.js'),
  fetchRaw('index.html'),
  fetchRaw('src/pages/ServiceDetailPage.jsx'),
  fetchRaw('src/pages/CaseStudiesPage.jsx'),
  fetchRaw('src/components/ContactForm.jsx'),
  fetchRaw('src/components/TrustStats.jsx'),
  fetchRaw('src/components/ChatVoiceWidget.jsx'),
]);

let domainLive = false;
try {
  const res = await this.helpers.httpRequest({ method: 'GET', url: 'https://openmind.in/', returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 10000 });
  domainLive = res.statusCode >= 200 && res.statusCode < 300 && String(res.body).includes('G-C9EKCGDXZN');
} catch (e) { domainLive = false; }

return [{
  json: {
    checks: [
      { label: 'Domain openmind.in is live on this site', done: domainLive },
      { label: 'vite.config.js ready for the real domain (base path is "/")', done: !!viteConfig && !viteConfig.includes("'/openmind360/'") },
      { label: 'Demo Slot placeholder removed from service pages', done: !!serviceDetailJsx && !serviceDetailJsx.includes('Demo Slot') },
      { label: 'Case Studies filled in (no empty industry tabs)', done: !!caseStudiesJsx && !caseStudiesJsx.includes('cases: []') },
      { label: 'Contact form connected to n8n (07/08 live)', done: !!contactForm && !contactForm.includes('YOUR-N8N-DOMAIN') && !!trustStats && !trustStats.includes('YOUR-N8N-DOMAIN') },
      { label: 'Live chatbot connected to n8n (09-11 live)', done: !!chatWidget && !chatWidget.includes('YOUR-N8N-DOMAIN') },
    ],
  },
}];

// Combines both checks into one plain-English email. No AI writing here on
// purpose — every line is a fact, not a guess.
const siteChecks = $('Check Website & Code').first().json.checks;

let n8nWorkflows = [];
try {
  const wf = $('Check n8n Workflows').first().json;
  n8nWorkflows = Array.isArray(wf) ? wf : (wf && Array.isArray(wf.data) ? wf.data : []);
} catch (e) { n8nWorkflows = []; }
const n8nOk = n8nWorkflows.length > 0;
const importedCount = n8nOk ? [...Array(13)].filter((_, i) => n8nWorkflows.some((w) => typeof w.name === 'string' && w.name.startsWith(String(i + 1).padStart(2, '0') + ' -'))).length : 0;

const checks = [
  ...siteChecks,
  { label: `n8n workflows imported (${importedCount} of 13 found)`, done: importedCount === 13 },
];
if (!n8nOk) checks.push({ label: 'n8n could not be reached to check workflow status — fix the N8N_BASE_URL / API key in this workflow', done: false });

const doneCount = checks.filter((c) => c.done).length;
function esc(s) { return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
const rows = checks.map((c) => `<li>${c.done ? '✅' : '⬜'} ${esc(c.label)}</li>`).join('');

const html = `<h2>Openmind Project — Weekly Status</h2><p>${doneCount} of ${checks.length} checked automatically from the real code and site — nobody typed these in.</p><ul>${rows}</ul><p>Full project notes: <a href="https://github.com/inder20216/openmind360/blob/main/PROJECT-STATUS.md">PROJECT-STATUS.md</a></p>`;

return [{ json: { html, subject: `Openmind Project — Weekly Status (${new Date().toLocaleDateString('en-IN')})` } }];
